/*
 * A073899  a(1) = 1; then k-th prime prime(k) followed by prime(k)
 *          consecutive composite numbers not occurring earlier.
 * https://oeis.org/A073899
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(1)=1; for each k≥1 append prime(k) and then prime(k) *
 *            distinct composite numbers not appearing earlier. The sequence *
 *            is generated by a greedy algorithm that keeps track of
 *            composites * already used. The function memoises previously
 *            computed values * so calls in any order are fast. It is vali...
 * Range:     u8 n <= 62, u16 n <= 62, u32 n <= 62, u64 n <= 62, u128 n <= 62,
 *            big any n
 * Helpers:   get_prime, is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdbool.h>
#include <stddef.h>
#include "../utils/get_prime.h"
#include "../utils/is_prime.h"

/* Static storage for the computed sequence. */
static seq_t *seq = NULL;
static size_t seq_cap = 0;
static idx_t seq_len = 0;

/* Static storage for marking composites that have already
 * appeared in the sequence.  Indices correspond to integer values.
 */
static bool *used = NULL;
static idx_t used_cap = 0;
static idx_t next_candidate = 2;    /* start searching composites from 2 */

/* Current state of the construction process. */
static idx_t current_k = 1;         /* k such that prime(k) is next needed */
static uint32_t current_prime = 0;  /* value of prime(k) */
static idx_t composites_needed = 0; /* remaining composites to emit for current k */

/* Ensure the seq array has capacity for at least ‘needed’ elements. */
static void seq_ensure(size_t needed)
{
    if (needed <= seq_cap) return;
    size_t newcap = seq_cap ? seq_cap * 2 : 128;
    if (newcap < needed) newcap = needed;
    seq = (seq_t *)realloc(seq, newcap * sizeof(seq_t));
    seq_cap = newcap;
}

/* Ensure the used array can be indexed up to ‘size‑1’. */
static void used_ensure(idx_t size)
{
    if (size <= used_cap) return;
    size_t newcap = used_cap ? used_cap * 2 : 128;
    if ((idx_t)newcap < size) newcap = (size_t)size;
    bool *newused = (bool *)realloc(used, newcap * sizeof(bool));
    for (idx_t i = used_cap; i < (idx_t)newcap; ++i) newused[i] = false;
    used = newused;
    used_cap = (idx_t)newcap;
}

/* Append a single value to the sequence. */
static void seq_push(seq_t val)
{
    seq_ensure(seq_len + 1);
    seq[seq_len++] = val;
}

/* Initialise the sequence with its very first term, 1. */
static void init_sequence(void)
{
    seq_push((seq_t)1);
}

/* Main OEIS sequence function. */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;   /* undefined for n=0, guard */
    if (seq_len == 0) init_sequence();

    /* Extend the sequence until we have at least n terms */
    while (seq_len < n) {
        /* If we have finished a block, start the next block with its prime. */
        if (composites_needed == 0) {
            current_prime = get_prime(current_k); /* obtain prime(k) */
            seq_push((seq_t)current_prime);
            composites_needed = (idx_t)current_prime;
            ++current_k;
            continue;
        }

        /* Emit composites until this block is finished. */
        while (composites_needed > 0 && seq_len < n) {
            /* Find the next unused composite number. */
            while (true) {
                used_ensure(next_candidate + 1);
                if (used[next_candidate]) {          /* already used as composite */
                    ++next_candidate;
                    continue;
                }
                if (is_prime(next_candidate)) {      /* skip primes */
                    ++next_candidate;
                    continue;
                }
                /* Found a new composite number. */
                used[next_candidate] = true;
                seq_push((seq_t)next_candidate);
                --composites_needed;
                ++next_candidate;
                break;
            }
        }
    }

    /* Return the requested element (1‑based). */
    return seq[n - 1];
}
